import pandas as pd
import numpy as np

# Set a random seed for reproducibility
np.random.seed(42)

# Number of customers
n_customers = 1000

# Generate synthetic data
data = {
    'customerID': [f'C{i:04d}' for i in range(n_customers)],
    'gender': np.random.choice(['Male', 'Female'], n_customers),
    'SeniorCitizen': np.random.choice([0, 1], n_customers, p=[0.8, 0.2]),
    'Partner': np.random.choice(['Yes', 'No'], n_customers),
    'Dependents': np.random.choice(['Yes', 'No'], n_customers),
    'tenure': np.random.randint(1, 73, n_customers), # Months
    'PhoneService': np.random.choice(['Yes', 'No'], n_customers),
    'MultipleLines': np.random.choice(['No phone service', 'No', 'Yes'], n_customers),
    'InternetService': np.random.choice(['DSL', 'Fiber optic', 'No'], n_customers, p=[0.35, 0.45, 0.20]),
    'OnlineSecurity': np.random.choice(['No', 'Yes', 'No internet service'], n_customers),
    'OnlineBackup': np.random.choice(['No', 'Yes', 'No internet service'], n_customers),
    'DeviceProtection': np.random.choice(['No', 'Yes', 'No internet service'], n_customers),
    'TechSupport': np.random.choice(['No', 'Yes', 'No internet service'], n_customers),
    'StreamingTV': np.random.choice(['No', 'Yes', 'No internet service'], n_customers),
    'StreamingMovies': np.random.choice(['No', 'Yes', 'No internet service'], n_customers),
    'Contract': np.random.choice(['Month-to-month', 'One year', 'Two year'], n_customers, p=[0.5, 0.3, 0.2]),
    'PaperlessBilling': np.random.choice(['Yes', 'No'], n_customers),
    'PaymentMethod': np.random.choice(['Electronic check', 'Mailed check', 'Bank transfer (automatic)', 'Credit card (automatic)'], n_customers),
    'MonthlyCharges': np.random.uniform(18.00, 120.00, n_customers).round(2)
}

churn_df = pd.DataFrame(data)

# Generate TotalCharges based on tenure and MonthlyCharges, with some missing values
churn_df['TotalCharges'] = churn_df['tenure'] * churn_df['MonthlyCharges']
churn_df.loc[churn_df['tenure'] == 0, 'TotalCharges'] = np.nan # Simulate some missing values for new customers
churn_df['TotalCharges'] = churn_df['TotalCharges'].round(2).astype(str) # Convert to string to simulate real-world data issues

# Introduce some 'No internet service' to be consistent with other internet-related features
churn_df.loc[churn_df['InternetService'] == 'No', ['OnlineSecurity', 'OnlineBackup', 'DeviceProtection', 'TechSupport', 'StreamingTV', 'StreamingMovies']] = 'No internet service'

# Introduce 'Churn' based on factors like MonthlyCharges, Contract, and Tenure
# Customers with higher monthly charges, shorter contracts, and shorter tenure are more likely to churn
churn_df['Churn'] = 0
churn_df.loc[(churn_df['MonthlyCharges'] > 70) & (churn_df['Contract'] == 'Month-to-month') & (churn_df['tenure'] < 24), 'Churn'] = np.random.choice([0, 1], sum((churn_df['MonthlyCharges'] > 70) & (churn_df['Contract'] == 'Month-to-month') & (churn_df['tenure'] < 24)), p=[0.3, 0.7])
churn_df.loc[(churn_df['MonthlyCharges'] < 50) & (churn_df['Contract'] == 'Two year') & (churn_df['tenure'] > 36), 'Churn'] = np.random.choice([0, 1], sum((churn_df['MonthlyCharges'] < 50) & (churn_df['Contract'] == 'Two year') & (churn_df['tenure'] > 36)), p=[0.9, 0.1])
churn_df['Churn'] = np.random.choice([0, 1], n_customers, p=[0.75, 0.25]) # Base churn rate

print("Simulated Customer Churn Dataset created.")

# Display the first five rows of the DataFrame
print("\nFirst 5 rows of the dataset:")
print(churn_df.head())

# Examine column names and their data types
print("\nDataFrame Info:")
churn_df.info()

