"""**Reasoning**:
The subtask requires data cleaning and preprocessing. I will start by converting 'TotalCharges' to a numeric type, handling missing values, dropping the 'customerID' column, and then performing one-hot encoding on the remaining categorical features. This prepares the data for model training as per the instructions.


"""

print("Starting data preprocessing...")

# 1. Convert 'TotalCharges' to numeric, coercing errors to NaN
churn_df['TotalCharges'] = pd.to_numeric(churn_df['TotalCharges'], errors='coerce')
print("Converted 'TotalCharges' to numeric, coercing errors to NaN.")

# 2. Handle missing values in 'TotalCharges' by filling with the median
median_total_charges = churn_df['TotalCharges'].median()
churn_df['TotalCharges'] = churn_df['TotalCharges'].fillna(median_total_charges)
print(f"Filled missing 'TotalCharges' with median value: {median_total_charges}")

# 3. Drop the 'customerID' column if it exists
if 'customerID' in churn_df.columns:
    churn_df.drop('customerID', axis=1, inplace=True)
    print("Dropped 'customerID' column.")
else:
    print("'customerID' column not found, skipping drop.")

# 4. Identify all columns with object data type (categorical columns)
categorical_cols = churn_df.select_dtypes(include=['object']).columns
print(f"Identified categorical columns for one-hot encoding: {list(categorical_cols)}")

# 5. Apply one-hot encoding to these identified categorical columns
churn_df = pd.get_dummies(churn_df, columns=categorical_cols, drop_first=True)
print("Applied one-hot encoding to categorical columns.")

print("Data preprocessing complete. Displaying first 5 rows of the processed DataFrame:")
print(churn_df.head())
print("\nDataFrame Info after preprocessing:")
churn_df.info()

