from sklearn.model_selection import train_test_split
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score

print("Starting model training and evaluation...")

# 1. Separate features (X) and target variable (y)
X = churn_df.drop('Churn', axis=1)
y = churn_df['Churn']
print("Separated features (X) and target (y).")

# 2. Split the dataset into training and testing sets
X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3, random_state=42)
print("Data split into training and testing sets (70% train, 30% test).")

# 3. Instantiate a logistic regression model
# Increased max_iter for convergence on potentially complex synthetic data
model = LogisticRegression(random_state=42, solver='liblinear', max_iter=200)
print("Logistic Regression model instantiated.")

# 4. Train the logistic regression model
model.fit(X_train, y_train)
print("Logistic Regression model trained.")

# 5. Make predictions on the test set
y_pred = model.predict(X_test)
print("Predictions made on the test set.")

# 6. Evaluate the model's performance
accuracy = accuracy_score(y_test, y_pred)
precision = precision_score(y_test, y_pred)
recall = recall_score(y_test, y_pred)
f1 = f1_score(y_test, y_pred)

print("\nModel Performance Metrics:")
print(f"Accuracy: {accuracy:.4f}")
print(f"Precision: {precision:.4f}")
print(f"Recall: {recall:.4f}")
print(f"F1-Score: {f1:.4f}")

print("Model training and evaluation complete.")

